// ================= i18n runtime (static site, no dependencies) =================
// Languages: zh-CN (default), zh-TW, en, de, ja, ko, fr.
// Language choice: manual selection (localStorage) > IP geolocation > browser language > zh-CN.
// The IP lookup is non-blocking: the page renders in the default language first,
// then switches once the lookup returns. All failures fall back gracefully.

(function () {
  var DEFAULT_LANG = 'zh-CN';
  var LS_KEY = 'ai-nav-lang';
  var state = { lang: DEFAULT_LANG, manual: false };
  var listeners = [];

  function dict() { return I18N_UI[state.lang] || I18N_UI[DEFAULT_LANG]; }
  function t(key) {
    var d = dict();
    if (d && d[key] !== undefined) return d[key];
    var base = I18N_UI[DEFAULT_LANG];
    return (base && base[key] !== undefined) ? base[key] : key;
  }
  function tf(key, vars) {
    var s = t(key);
    for (var k in vars) s = s.split('{' + k + '}').join(String(vars[k]));
    return s;
  }
  function cat(name) {
    var m = I18N_CATS[state.lang] || {};
    return m[name] || name;
  }
  function price(p) {
    var m = I18N_PRICE[state.lang] || {};
    return m[p] || p;
  }
  // Translated tool description/note/tags by DATA index; null => use original zh-CN.
  function desc(idx) {
    if (state.lang === DEFAULT_LANG) return null;
    var m = I18N_DESC[state.lang];
    return (m && m[String(idx)]) || null;
  }
  // Translated prompt title by prompt id; null => use original zh-CN.
  function title(id) {
    if (state.lang === DEFAULT_LANG) return null;
    var m = I18N_TITLES[state.lang];
    return (m && m[id]) || null;
  }

  // ---- country -> language ----
  function countryToLang(cc) {
    if (!cc) return null;
    cc = String(cc).toUpperCase();
    if (cc === 'TW' || cc === 'HK' || cc === 'MO') return 'zh-TW';
    if (cc === 'CN' || cc === 'SG' || cc === 'MY') return 'zh-CN';
    if (cc === 'JP') return 'ja';
    if (cc === 'KR') return 'ko';
    if (cc === 'DE' || cc === 'AT' || cc === 'CH' || cc === 'LI' || cc === 'LU') return 'de';
    if (cc === 'FR' || cc === 'BE' || cc === 'MC') return 'fr';
    if (cc === 'US' || cc === 'GB' || cc === 'AU' || cc === 'CA' || cc === 'NZ' || cc === 'IE' ||
        cc === 'IN' || cc === 'ZA' || cc === 'PH' || cc === 'NG' || cc === 'KE' ||
        cc === 'NL' || cc === 'SE' || cc === 'NO' || cc === 'DK' || cc === 'FI') return 'en';
    return 'zh-CN';
  }
  function navLang() {
    var l = (navigator.language || navigator.userLanguage || '').toLowerCase();
    if (l.indexOf('zh-tw') === 0 || l.indexOf('zh-hk') === 0 || l.indexOf('zh-mo') === 0) return 'zh-TW';
    if (l.indexOf('zh') === 0) return 'zh-CN';
    if (l.indexOf('en') === 0) return 'en';
    if (l.indexOf('de') === 0) return 'de';
    if (l.indexOf('ja') === 0) return 'ja';
    if (l.indexOf('ko') === 0) return 'ko';
    if (l.indexOf('fr') === 0) return 'fr';
    return 'zh-CN';
  }
  function via(url, pick) {
    if (typeof fetch !== 'function') return Promise.resolve(null);
    return fetch(url, { method: 'GET' }).then(function (r) {
      if (!r.ok) throw new Error('http ' + r.status);
      return r.json();
    }).then(function (j) {
      var cc = pick(j);
      return cc ? countryToLang(cc) : null;
    }).catch(function () { return null; });
  }
  function detectByIP() {
    return via('https://ipwho.is/', function (j) { return j && j.country_code; })
      .then(function (lang) {
        if (lang) return lang;
        return via('https://ipapi.co/json/', function (j) { return j && j.country_code; });
      });
  }

  // ---- apply language to static text ----
  function applyStatic() {
    document.documentElement.lang = state.lang;
    document.title = t('meta.title');
    var md = document.querySelector('meta[name="description"]');
    if (md) md.setAttribute('content', t('meta.desc'));
    var els = document.querySelectorAll('[data-i18n]');
    for (var i = 0; i < els.length; i++) els[i].textContent = t(els[i].getAttribute('data-i18n'));
    var htmls = document.querySelectorAll('[data-i18n-html]');
    for (var j = 0; j < htmls.length; j++) htmls[j].innerHTML = t(htmls[j].getAttribute('data-i18n-html'));
    var phs = document.querySelectorAll('[data-i18n-ph]');
    for (var k = 0; k < phs.length; k++) phs[k].setAttribute('placeholder', t(phs[k].getAttribute('data-i18n-ph')));
    var pers = document.querySelectorAll('[data-i18n-per]');
    for (var m = 0; m < pers.length; m++) {
      pers[m].textContent = tf('pricing.per', { n: pers[m].getAttribute('data-i18n-per') });
    }
    var sel = document.getElementById('langSelect');
    if (sel) sel.value = state.lang;
  }

  function setLang(lang, opts) {
    opts = opts || {};
    if (I18N_LANGS.indexOf(lang) < 0) lang = DEFAULT_LANG;
    state.lang = lang;
    if (opts.save) {
      try { localStorage.setItem(LS_KEY, lang); } catch (e) {}
      state.manual = true;
    }
    applyStatic();
    for (var i = 0; i < listeners.length; i++) {
      try { listeners[i](lang); } catch (e) {}
    }
  }

  function buildSwitcher() {
    var sel = document.getElementById('langSelect');
    if (!sel) return;
    var labels = { 'zh-CN': '简体中文', 'zh-TW': '繁體中文', 'en': 'English', 'de': 'Deutsch', 'ja': '日本語', 'ko': '한국어', 'fr': 'Français' };
    I18N_LANGS.forEach(function (code) {
      var o = document.createElement('option');
      o.value = code;
      o.textContent = labels[code] || code;
      sel.appendChild(o);
    });
    sel.value = state.lang;
    sel.addEventListener('change', function () { setLang(sel.value, { save: true }); });
  }

  function init() {
    buildSwitcher();
    var saved = null;
    try { saved = localStorage.getItem(LS_KEY); } catch (e) {}
    if (saved && I18N_LANGS.indexOf(saved) >= 0) {
      state.manual = true;
      setLang(saved, {});
      return;
    }
    applyStatic();
    // Non-blocking IP detection; page already renders in the default language.
    var ip;
    try { ip = detectByIP(); } catch (e) { ip = Promise.resolve(null); }
    ip.then(function (lang) {
      if (state.manual) return;
      setLang(lang || navLang(), {});
    });
  }

  window.I18N = {
    langs: I18N_LANGS, state: state,
    t: t, tf: tf, cat: cat, price: price, desc: desc, title: title,
    setLang: setLang,
    onChange: function (fn) { listeners.push(fn); },
    init: init
  };

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
